AL_U8 RecvData[RECV_SIZE] = { 0x0 };

/************************** Function Prototypes ******************************/

/************************** Function Definitions ******************************/
/**
 * @note Chip SPI MOSI link Master MOSI when Chip as Slave
*/
AL_S32 main(void)
{
    AL_S32 Ret = AL_OK;

    AL_LOG(AL_LOG_LEVEL_ERROR, "Start FPSoc Spi Master Test\r\n");

    Ret = AlSpi_Hal_Init(&Handle, &SpiInitConfigs, (SPI_EventCallBack)AL_NULL, AL_SPI_DEVICE_ID);
    if (AL_OK != Ret) {
        AL_LOG(AL_LOG_LEVEL_ERROR, "AlSpi_Hal_Init error, Ret:0x%x\r\n", Ret);
        return Ret;
    }

    /* full duplex mode */
    Handle->Dev.Configs.Trans.TransMode  = SPI_TX_RX;
    Ret = AlSpi_Hal_TranferDataPolling(Handle, SendData, SEND_SIZE, RecvData, RECV_SIZE);
    if (AL_OK != Ret) {
        AL_LOG(AL_LOG_LEVEL_ERROR, "AlSpi_Hal_TranferDataPolling error, Ret:0x%x\r\n", Ret);
        return Ret;
    }

    AL_LOG(AL_LOG_LEVEL_INFO, "AlSpi_Hal_TranferDataPolling Recv Data:\r\n");
    for (AL_U32 Index = 0; Index < RECV_SIZE; Index++) {
        AL_LOG(AL_LOG_LEVEL_INFO, "0x%x ", RecvData[Index]);
        if ((Index+1) % 16 == 0) {
            AL_LOG(AL_LOG_LEVEL_INFO, "\r\n");
        }
    }

    return AL_OK;
}